import csv
from datetime import datetime
from decimal import Decimal
from collections import defaultdict, Counter
rows=list(csv.DictReader(open('expenses.csv')))
def parsedate(s):
    for fmt in ('%m/%d/%Y','%d %b %Y','%Y-%m-%d'):
        try:return datetime.strptime(s.strip(),fmt).date()
        except ValueError:pass
def amount(s):
    return Decimal(s.strip().replace('$','').replace('USD','').strip())
seen=set(); clean=[]
for r in rows:
    d=parsedate(r['date']); a=amount(r['amount']); c=r['category'].strip().lower(); st=r['status'].strip().lower()
    key=(r['id'].strip(),d,c,a,r['amount'].strip().lower(),st)
    dup=key in seen
    seen.add(key)
    if d.year==2026 and d.month==10 and st!='void' and not dup:
        clean.append((d,int(r['id']),c,a))
clean.sort()
print('count',len(clean),'total',sum(x[3] for x in clean))
for d,i,c,a in clean: print(d,i,c,a)
cat=defaultdict(Decimal); n=defaultdict(int)
for d,i,c,a in clean: cat[c]+=a; n[c]+=1
for c in sorted(cat, key=lambda c:(-cat[c],c)):
    print(f'{c:10} {n[c]:2} {cat[c]:>8} {cat[c]/sum(cat.values())*100:5.1f}%')
print('void oct count',sum(1 for r in rows if parsedate(r['date']).year==2026 and parsedate(r['date']).month==10 and r['status'].strip()=='void'))
print('oct total rows',sum(1 for r in rows if parsedate(r['date']).year==2026 and parsedate(r['date']).month==10))
PY", "description": "Compute October cleaned totals and category breakdown"}

