import re
from decimal import Decimal
text=open('report.md').read()
rows=[]
for line in text.splitlines():
    m=re.match(r'\|\s*(\d{4}-\d{2}-\d{2})\s*\|\s*(\d+)\s*\|\s*([^|]+?)\s*\|\s*\$([\d,.]+)\s*\|',line)
    if m: rows.append((m.group(1),m.group(2),m.group(3).strip(),Decimal(m.group(4).replace(',',''))))
print('rows',len(rows),'total',sum(r[3] for r in rows))
from collections import defaultdict
c=defaultdict(lambda:[0,Decimal(0)])
for _,_,cat,a in rows:
    c[cat][0]+=1;c[cat][1]+=a
for k,v in sorted(c.items(), key=lambda kv:-kv[1][1]): print(k,v)
# parse category table rows
catrows={}
for line in text.splitlines():
    m=re.match(r'\|\s*([A-Za-z ]+?)\s*\|\s*(\d+)\s*\|\s*\$([\d,.]+)\s*\|\s*[\d.]+%\s*\|',line)
    if m and m.group(1).strip()!='Category': catrows[m.group(1).strip()]=(int(m.group(2)),Decimal(m.group(3).replace(',','')))
print('cat table',catrows)
print('match', {k:(c[k][0],c[k][1])==v for k,v in catrows.items() if k!='Total'})
PY", "description": "Verify report transaction and category totals"}

